#!/bin/sh
# Generated by FWShift: AWS EC2 security groups for one VPC, created with the AWS CLI. Read the report first:
# what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                 prints the calls, makes none (no AWS access needed)
#   VPC_ID=vpc-... CHECK=1 sh THIS_FILE    sends every call with --dry-run: AWS checks the permissions
#   VPC_ID=vpc-... sh THIS_FILE            creates the groups and their rules
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The groups are created WITHOUT members: nothing changes for any traffic until they are attached. Attach each
# group to the network interfaces whose private addresses are listed after it (# attach ...): an interface gets
# every group whose list holds one of its addresses, and then no other groups. A group of the same name in the
# VPC stops the script before anything is created; a call AWS refuses stops it where it is (delete the groups
# it made with aws ec2 delete-security-group --group-id ... and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
if [ -z "$DRY_RUN" ]; then
  : "${VPC_ID:?set VPC_ID to the id of the VPC (vpc-...), or DRY_RUN=1 to print the calls}"
else
  VPC_ID="${VPC_ID:-vpc-DRYRUN}"
fi
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws ec2' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
# change CALL ARGS...: a call that changes something
change() {
  if [ -n "$DRY_RUN" ]; then show "$@"; return 0; fi
  if [ -n "$CHECK" ]; then
    out=$(aws ec2 "$@" --dry-run $AWS_OPTS 2>&1)
    case "$out" in *DryRunOperation*) printf 'checked: %s\n' "$1" >&2; return 0 ;; esac
    fail "aws ec2 $1: $out"
  fi
  aws ec2 "$@" $AWS_OPTS >/dev/null || fail "aws ec2 $1"
}
# free NAME: stops the script when the VPC has a group of that name
free() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  found=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=$1" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "describe-security-groups: $found"
  [ "$found" = None ] || fail "a group named $1 exists in $VPC_ID already ($found); nothing was created"
}
# revoke GROUP PERMISSIONS: takes an outbound rule off a new group; a rule that is not there is fine
revoke() {
  out=$(aws ec2 revoke-security-group-egress --group-id "$1" --ip-permissions "$2" $AWS_OPTS 2>&1) && return 0
  case "$out" in *InvalidPermission.NotFound*|*InvalidParameterValue*) return 0 ;; esac
  fail "revoke-security-group-egress $1: $out"
}
# group NAME DESCRIPTION: creates a group without rules and prints its id
group() {
  if [ -n "$DRY_RUN" ]; then show create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf 'sg-dryrun-%s\n' "$1"; return 0; fi
  if [ -n "$CHECK" ]; then change create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf '%s\n' "$STAND_IN"; return 0; fi
  id=$(aws ec2 create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID" --tag-specifications '[{"ResourceType":"security-group","Tags":[{"Key":"fwshift","Value":"generated"}]}]' --query GroupId --output text $AWS_OPTS) || fail "create-security-group $1"
  aws ec2 wait security-group-exists --group-ids "$id" $AWS_OPTS || fail "group $id did not appear"
  # A new group allows everything outbound (IPv4, and IPv6 where the VPC has it): take that off, and make sure.
  revoke "$id" '[{"IpProtocol":"-1","IpRanges":[{"CidrIp":"0.0.0.0/0"}]}]'
  revoke "$id" '[{"IpProtocol":"-1","Ipv6Ranges":[{"CidrIpv6":"::/0"}]}]'
  left=$(aws ec2 describe-security-group-rules --filters "Name=group-id,Values=$id" --query 'length(SecurityGroupRules[?IsEgress])' --output text $AWS_OPTS) || fail "describe-security-group-rules $id"
  [ "$left" = 0 ] || fail "group $id still has $left outbound rules; it was not given any others"
  printf 'created %s %s\n' "$1" "$id" >&2
  printf '%s\n' "$id"
}
ingress() { perms=$(cat); change authorize-security-group-ingress --group-id "$1" --ip-permissions "$perms"; }
egress() { perms=$(cat); change authorize-security-group-egress --group-id "$1" --ip-permissions "$perms"; }
STAND_IN=""
if [ -z "$DRY_RUN" ] && [ -n "$CHECK" ]; then
  STAND_IN=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=default" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "no default group in $VPC_ID"
fi

# No group of these names may exist.
free 'fwshift-guest_net'
free 'fwshift-dmz'
free 'fwshift-mail_srv'
free 'fwshift-web_srv'
free 'fwshift-dmz-2'
free 'fwshift-lan_net'
free 'fwshift-wan_net'
free 'fwshift-addresses-ipv6'
free 'fwshift-lan_net6-ipv6'
free 'fwshift-no-rules'

# The groups, each with the private addresses of the network interfaces it is for.
# attach fwshift-guest_net: 10.30.0.0/24
G1=$(group 'fwshift-guest_net' 'FWShift: for the interfaces of 10.30.0.0/24') || exit 1
# attach fwshift-dmz: 172.16.20.0-172.16.20.24 172.16.20.26-172.16.20.79 172.16.20.81-172.16.20.99 172.16.20.104-172.16.20.255
G2=$(group 'fwshift-dmz' 'FWShift: for the interfaces of 172.16.20.0-172.16.20.24 172.16.20.26-172.16.20.79 172.16.20.81-172.16.20.99 172.16.20.104-172.16.20.255') || exit 1
# attach fwshift-mail_srv: 172.16.20.25
G3=$(group 'fwshift-mail_srv' 'FWShift: for the interfaces of 172.16.20.25') || exit 1
# attach fwshift-web_srv: 172.16.20.80
G4=$(group 'fwshift-web_srv' 'FWShift: for the interfaces of 172.16.20.80') || exit 1
# attach fwshift-dmz-2: 172.16.20.100/30
G5=$(group 'fwshift-dmz-2' 'FWShift: for the interfaces of 172.16.20.100/30') || exit 1
# attach fwshift-lan_net: 192.168.10.0/24
G6=$(group 'fwshift-lan_net' 'FWShift: for the interfaces of 192.168.10.0/24') || exit 1
# attach fwshift-wan_net: 203.0.113.0/24
G7=$(group 'fwshift-wan_net' 'FWShift: for the interfaces of 203.0.113.0/24') || exit 1
# attach fwshift-addresses-ipv6: ::-2001:db8:f:ffff:ffff:ffff:ffff:ffff 2001:db8:10:1::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
G8=$(group 'fwshift-addresses-ipv6' 'FWShift: for the interfaces of ::-2001:db8:f:ffff:ffff:ffff:ffff:ffff 2001:db8:10:1::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-lan_net6-ipv6: 2001:db8:10::/64
G9=$(group 'fwshift-lan_net6-ipv6' 'FWShift: for the interfaces of 2001:db8:10::/64') || exit 1
# attach fwshift-no-rules: 0.0.0.0-10.29.255.255 10.30.1.0-172.16.19.255 172.16.21.0-192.168.9.255 192.168.11.0-203.0.112.255 203.0.114.0-255.255.255.255
G10=$(group 'fwshift-no-rules' 'FWShift: for the interfaces of 0.0.0.0-10.29.255.255 10.30.1.0-172.16.19.255 172.16.21.0-192.168.9.255 192.168.11.0-203.0.112.255 203.0.114.0-255.255.255.255') || exit 1

# Their rules: inbound rules name the sources, outbound rules the destinations.
egress "$G1" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 25, "ToPort": 25, "IpRanges": [{"CidrIp": "172.16.20.25/32", "Description": "FWShift: nat_mail+sat_mail"}]}, {"IpProtocol": "tcp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: to_guest/guest_dns"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: to_guest/guest_web"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: to_guest/guest_web"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: to_guest/guest_dns"}]}]
FWSHIFT_JSON
ingress "$G2" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: lan_to_dmz"}]}]
FWSHIFT_JSON
egress "$G2" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}]
FWSHIFT_JSON
ingress "$G3" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: lan_to_dmz"}]}, {"IpProtocol": "tcp", "FromPort": 25, "ToPort": 25, "IpRanges": [{"CidrIp": "10.30.0.0/24", "Description": "FWShift: nat_mail+sat_mail, allow_mail+sat_mail"}, {"CidrIp": "203.0.113.0/24", "Description": "FWShift: nat_mail+sat_mail, allow_mail+sat_mail"}]}]
FWSHIFT_JSON
egress "$G3" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}]
FWSHIFT_JSON
ingress "$G4" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: lan_to_dmz"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: allow_web+sat_web"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: allow_web+sat_web, admin_mgmt"}]}, {"IpProtocol": "tcp", "FromPort": 8443, "ToPort": 8443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_https"}]}]
FWSHIFT_JSON
egress "$G4" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}]
FWSHIFT_JSON
ingress "$G5" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: lan_to_dmz"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: allow_pool+sat_pool"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: allow_pool+sat_pool"}]}, {"IpProtocol": "tcp", "FromPort": 8080, "ToPort": 8090, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: allow_pool+sat_pool"}]}]
FWSHIFT_JSON
egress "$G5" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: pol_dmz_out"}]}]
FWSHIFT_JSON
egress "$G6" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: lan_to_dmz"}]}, {"IpProtocol": "tcp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: lan_dns"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: lan_web"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: lan_web"}]}, {"IpProtocol": "tcp", "FromPort": 8080, "ToPort": 8090, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: lan_web"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/24", "Description": "FWShift: lan_dns"}]}]
FWSHIFT_JSON
ingress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "10.30.0.0/24", "Description": "FWShift: to_guest/guest_dns, lan_dns"}, {"CidrIp": "192.168.10.0/24", "Description": "FWShift: to_guest/guest_dns, lan_dns"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "10.30.0.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}, {"CidrIp": "172.16.20.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}, {"CidrIp": "192.168.10.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "10.30.0.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}, {"CidrIp": "172.16.20.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}, {"CidrIp": "192.168.10.0/24", "Description": "FWShift: to_guest/guest_web, lan_web, pol_dmz_out"}]}, {"IpProtocol": "tcp", "FromPort": 8080, "ToPort": 8090, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: lan_web"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "10.30.0.0/24", "Description": "FWShift: to_guest/guest_dns, lan_dns"}, {"CidrIp": "192.168.10.0/24", "Description": "FWShift: to_guest/guest_dns, lan_dns"}]}]
FWSHIFT_JSON
egress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 25, "ToPort": 25, "IpRanges": [{"CidrIp": "172.16.20.25/32", "Description": "FWShift: allow_mail+sat_mail"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "172.16.20.80/32", "Description": "FWShift: allow_web+sat_web, allow_pool+sat_pool"}, {"CidrIp": "172.16.20.100/30", "Description": "FWShift: allow_web+sat_web, allow_pool+sat_pool"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "172.16.20.80/32", "Description": "FWShift: allow_web+sat_web, allow_pool+sat_pool"}, {"CidrIp": "172.16.20.100/30", "Description": "FWShift: allow_web+sat_web, allow_pool+sat_pool"}]}, {"IpProtocol": "tcp", "FromPort": 8080, "ToPort": 8090, "IpRanges": [{"CidrIp": "172.16.20.100/30", "Description": "FWShift: allow_pool+sat_pool"}]}, {"IpProtocol": "tcp", "FromPort": 8443, "ToPort": 8443, "IpRanges": [{"CidrIp": "172.16.20.80/32", "Description": "FWShift: pol_dmz_https"}]}]
FWSHIFT_JSON
ingress "$G8" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmpv6", "FromPort": 128, "ToPort": -1, "Ipv6Ranges": [{"CidrIpv6": "2001:db8:10::/64", "Description": "FWShift: lan6_ping"}]}]
FWSHIFT_JSON
ingress "$G9" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmpv6", "FromPort": 128, "ToPort": -1, "Ipv6Ranges": [{"CidrIpv6": "2001:db8:10::/64", "Description": "FWShift: lan6_ping"}]}]
FWSHIFT_JSON
egress "$G9" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmpv6", "FromPort": 128, "ToPort": -1, "Ipv6Ranges": [{"CidrIpv6": "::/0", "Description": "FWShift: lan6_ping"}]}]
FWSHIFT_JSON

# Not written:
#   rule drop_netbios: not written, see the report
#   rule to_guest/guest_never: disabled in the source, not written
#   rule lan_updates: not written, see the report
#   rule syslog_fast: not written, see the report
#   rule gre_tunnel: not written, see the report
#   rule old_rule: disabled in the source, not written

echo 'Done. Attach the groups to the network interfaces the comments above name; until then nothing changes.' >&2
